{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Melagatran, a polar peptidomimetic, has human oral bioavailability of only 0.9% after food and 3–7% overall, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Epanolol, a polar drug with multiple hydrogen-bonding groups, has absolute oral bioavailability of about 7% in fasted volunteers, well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Aliskiren, a high-molecular-weight peptidomimetic, has absolute oral bioavailability of 2.5–2.6% in humans, supporting low F for similarly large polar peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Alvimopan, a zwitterionic peptide-like antagonist, has systemic oral bioavailability of approximately 6% in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Batefenterol, a large polar molecule, has absolute oral bioavailability of 0.012% in healthy subjects, indicating negligible oral absorption for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Linaclotide, a peptide drug, has low oral bioavailability in humans with systemic exposure limited to the gastrointestinal tract, consistent with low F for large peptide structures.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an extremely large, highly polar, fully ionized peptide (MW >4100 Da, TPSA >1600 Å², HBD 57, HBA 56, logD -19.4). Multiple high-transfer experimental analogues—peptidomimetics and polar drugs—show absolute oral bioavailability values of 0.01–10%, all below 20%. No evidence supports F ≥20%, so the prediction is low.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement exists for the exact query molecule.",
    "Active transport or unusual absorption mechanisms were not directly tested, but are highly unlikely for a molecule of this size and polarity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

